import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, it } from 'node:test';

/**
 * AuthContextStore is generated by the Android config plugin, so its Kotlin
 * implementation is not part of the TypeScript test graph. Keep the
 * fail-closed migration invariant covered at the source boundary instead.
 */
const PLUGIN_SOURCE = readFileSync(
  resolve(process.cwd(), 'plugins/withNativeIncomingCallAndroid.cjs'),
  'utf8',
);
const DOWNLOAD_AUTH_SOURCE = readFileSync(
  resolve(process.cwd(), 'plugins/android-modules/downloads/AttachmentDownloadAuth.kt'),
  'utf8',
);

const authContextReadBlock = (): string => {
  const start = PLUGIN_SOURCE.indexOf('fun read(context: Context): StoredAuthContext?');
  const end = PLUGIN_SOURCE.indexOf('fun clear(context: Context)', start);
  assert.notEqual(start, -1, 'AuthContextStore.read must remain present');
  assert.notEqual(end, -1, 'AuthContextStore.clear must remain present');
  return PLUGIN_SOURCE.slice(start, end);
};

describe('Android protected auth handoff policy', () => {
  it('treats either protected field as authoritative and refuses partial-state fallback', () => {
    const source = authContextReadBlock();

    assert.match(source, /val hasCiphertext = prefs\.contains\(CIPHERTEXT_KEY\)/);
    assert.match(source, /val hasIv = prefs\.contains\(IV_KEY\)/);
    assert.match(source, /val hasProtectedMaterial = hasCiphertext \|\| hasIv/);
    assert.match(
      source,
      /if \(!hasCompleteProtectedValue\) \{[\s\S]*?refusing legacy fallback[\s\S]*?return null/,
    );
  });

  it('requires nonblank values before the protected decrypt path', () => {
    const source = authContextReadBlock();

    assert.match(
      source,
      /val hasCompleteProtectedValue =\s+!ciphertextValue\.isNullOrBlank\(\) && !ivValue\.isNullOrBlank\(\)/,
    );
  });

  it('checks protected-state completeness before reading the legacy token', () => {
    const source = authContextReadBlock();
    const protectedGuard = source.indexOf('if (hasProtectedMaterial)');
    const legacyRead = source.indexOf('val legacyToken = prefs.getString(LEGACY_TOKEN_KEY, null)');

    assert.ok(protectedGuard >= 0, 'protected-state guard must remain present');
    assert.ok(
      legacyRead > protectedGuard,
      'legacy migration must follow the protected-state guard',
    );
  });

  it('does not reintroduce a plaintext preference reader for background downloads', () => {
    assert.match(DOWNLOAD_AUTH_SOURCE, /import net\.juspay\.xynespaces\.AuthContextStore/);
    assert.match(DOWNLOAD_AUTH_SOURCE, /AuthContextStore\.read\(context\.applicationContext\)/);
    assert.doesNotMatch(DOWNLOAD_AUTH_SOURCE, /getSharedPreferences\(/);
    assert.doesNotMatch(DOWNLOAD_AUTH_SOURCE, /auth_token/);
  });
});
